import { ApiError, GoogleGenAI } from '@google/genai';

// Natural-sounding speech for Anbu's replies, generated by Gemini's text-to-speech
// models and streamed as raw 16-bit PCM so playback can start before the whole
// reply has been synthesised. Free-tier keys allow only a few requests per minute
// per model, so several models are rotated and a model that reports a quota error
// rests until Google says it can be used again. Only the words are sent: the TTS
// models sometimes read delivery notes ("Say warmly: …") aloud, so the warmth
// comes from the chosen voice.

export const SPEECH_SAMPLE_RATE = 24_000;
export const SPEECH_MIME = `audio/L16; rate=${SPEECH_SAMPLE_RATE}; channels=1`;

export type VoiceGender = 'FEMALE' | 'MALE';

export interface SpeechRequest {
  text: string;
  /** Anbu speaks with a woman's voice unless she chooses a man's. */
  gender?: VoiceGender;
  /**
   * Also try the slow models (those given a longer start time). Worth it only when
   * the device has no voice to fall back on: a late voice beats silence.
   */
  allowSlow?: boolean;
  signal?: AbortSignal;
}

export interface SpeechStream {
  model: string;
  chunks: AsyncIterable<Buffer>;
}

export interface SpeechOptions {
  apiKey: string;
  /**
   * Tried in order, skipping any that are resting after a quota or server error.
   * "model:ms" gives a slower model longer to start speaking.
   */
  models: string[];
  /** Prebuilt Gemini voice for each choice. */
  voices: Record<VoiceGender, string>;
  /** Give up on a model if it has produced no audio after this long. */
  firstAudioTimeoutMs: number;
  now?: () => number;
}

export class SpeechUnavailableError extends Error {
  constructor(message = 'Natural voice is not available right now.') {
    super(message);
    this.name = 'SpeechUnavailableError';
  }
}

/** Removes formatting that would otherwise be read aloud. */
export function cleanSpeechText(text: string): string {
  return text
    .replace(/\[Development mock[^\]]*\]/g, '')
    .replace(/[*_#`>~|]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * How long Google asks us to wait, from a 429 error body such as `"retryDelay": "59s"`.
 * A used-up daily quota without a hint rests the model for an hour.
 */
export function retryDelayMs(message: string): number | null {
  const match = /retryDelay\\?"?:\s*\\?"(\d+(?:\.\d+)?)s/.exec(message);
  if (match) return Math.ceil(Number(match[1]) * 1000);
  return /PerDay/i.test(message) ? 60 * 60_000 : null;
}

/** "model" or "model:ms" from configuration. */
function parseModel(entry: string, defaultMs: number): { model: string; firstAudioMs: number } {
  const [model, ms] = entry.split(':');
  const parsed = Number(ms);
  return { model: model!.trim(), firstAudioMs: ms && parsed > 0 ? parsed : defaultMs };
}

type Generate = (model: string, request: SpeechRequest, signal: AbortSignal) => Promise<AsyncIterable<Buffer>>;

export class GeminiSpeech {
  private readonly resting = new Map<string, number>();
  private readonly now: () => number;
  private readonly generate: Generate;

  constructor(
    private readonly options: SpeechOptions,
    generate?: Generate,
  ) {
    this.now = options.now ?? Date.now;
    const client = new GoogleGenAI({ apiKey: options.apiKey });
    this.generate =
      generate ??
      (async (model, request, signal) => {
        const stream = await client.models.generateContentStream({
          model,
          contents: [{ role: 'user', parts: [{ text: request.text }] }],
          config: {
            abortSignal: signal,
            responseModalities: ['AUDIO'],
            speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: options.voices[request.gender ?? 'FEMALE'] } } },
          },
        });
        return (async function* () {
          for await (const chunk of stream) {
            for (const part of chunk.candidates?.[0]?.content?.parts ?? []) {
              if (part.inlineData?.data) yield Buffer.from(part.inlineData.data, 'base64');
            }
          }
        })();
      });
  }

  /** True when at least one model is not resting. */
  get available(): boolean {
    return this.options.models.some((m) => !this.isResting(parseModel(m, 0).model));
  }

  private isResting(model: string): boolean {
    const until = this.resting.get(model);
    if (until === undefined) return false;
    if (until <= this.now()) {
      this.resting.delete(model);
      return false;
    }
    return true;
  }

  private rest(model: string, err: unknown): void {
    const message = err instanceof Error ? err.message : '';
    const status = err instanceof ApiError ? err.status : undefined;
    const ms = status === 429 ? (retryDelayMs(message) ?? 60_000) : 15_000;
    this.resting.set(model, this.now() + ms);
  }

  /**
   * Starts speech on the first model that produces audio. Throws
   * SpeechUnavailableError when none can, so the caller can fall back to the
   * device's own voice.
   */
  async stream(request: SpeechRequest): Promise<SpeechStream> {
    for (const entry of this.options.models) {
      const { model, firstAudioMs } = parseModel(entry, this.options.firstAudioTimeoutMs);
      if (request.signal?.aborted) break;
      if (firstAudioMs > this.options.firstAudioTimeoutMs && !request.allowSlow) continue;
      if (this.isResting(model)) continue;

      const controller = new AbortController();
      const onAbort = () => controller.abort();
      request.signal?.addEventListener('abort', onAbort, { once: true });
      let timer: NodeJS.Timeout | undefined;
      const tooSlow = new Promise<never>((_resolve, reject) => {
        timer = setTimeout(() => {
          controller.abort();
          reject(new Error('No audio in time'));
        }, firstAudioMs);
      });
      try {
        const iterator = (await Promise.race([this.generate(model, request, controller.signal), tooSlow]))[Symbol.asyncIterator]();
        const first = await Promise.race([iterator.next(), tooSlow]);
        clearTimeout(timer);
        if (first.done || first.value.length === 0) throw new Error('No audio returned');
        return {
          model,
          chunks: (async function* () {
            try {
              yield first.value;
              for (let next = await iterator.next(); !next.done; next = await iterator.next()) yield next.value;
            } finally {
              request.signal?.removeEventListener('abort', onAbort);
              controller.abort();
            }
          })(),
        };
      } catch (err) {
        clearTimeout(timer);
        request.signal?.removeEventListener('abort', onAbort);
        controller.abort();
        if (request.signal?.aborted) break;
        if (err instanceof ApiError && (err.status === 401 || err.status === 403)) {
          throw new SpeechUnavailableError('The Gemini key was rejected for speech.');
        }
        this.rest(model, err);
      }
    }
    throw new SpeechUnavailableError();
  }
}
